    main_toggle_plural: ` tillgänglighetsvarningar`,
    MISSING_ROOT: `Editoria11y hittade inga element som matchade konfigurationen för kontrollområdet: <code>%(root)</code>`,
    panelCheckAltText: `Kontrollera att varje bild beskriver vad den betyder i sitt sammanhang och att det inte finns några bilder av text.`,
    panelCheckOutline: `Här visas rubrikstrukturen. Kontrollera att den stämmer med hur innehållet är organiserat visuellt.`,
    reportsLink: "Öppna webbplatsrapporter",
    toggleDisabled: "Inget innehåll tillgängligt för Editoria11y att kontrollera.",
    transferFocus: "Redigera detta innehåll",
    unDismissHideButton: "Återställ denna ignorerade varning",
